def longestEmbeddedSubstring(s, t):
    n = len(t)
    prev = [0] * (n + 1)
    best = 0
    for i in range(1, len(s) + 1):
        cur = [0] * (n + 1)
        c = s[i - 1]
        for j in range(1, n + 1):
            v = cur[j - 1]
            if c == t[j - 1] and prev[j - 1] + 1 > v:
                v = prev[j - 1] + 1
            cur[j] = v
        if cur[n] > best:
            best = cur[n]
        prev = cur
    return best
